	for {
		retryTimes--
		data, err = m.request.Invoke(algoData)
		if err != nil && retryTimes == 0 {
			return data, err
		} else if err == nil {
			break
		} else if err != nil {
			log.Warning("eas request fail :" + err.Error())
		}
	}

	if m.request.GetResponseFunc() != nil {
		return m.request.GetResponseFunc()(data)
	}

	return data, err
}

package aichat

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math/rand"
	"net/http"
	"strings"
	"time"

	"github.com/alibaba/pairec/v2/log"
	"github.com/alibaba/pairec/v2/recconf"
)

const (
	defaultPAIModelRegion  = "cn-beijing"
	defaultPAIModelTimeout = 60000
	paiModelEndpointFormat = "https://%s.pai-token.aliyuncs.com/v1"
	paiTokenChannel        = "pairec_agent"
)

type chatCompletionPayload struct {
	*ChatCompletionRequest
	ExtraBody map[string]string `json:"extra_body"`
}

type Model struct {
	name     string
	conf     recconf.PAIModelConfig
	client   *http.Client
	apiKey   string
	endpoint string
}

func NewModel(name string) *Model {
	return &Model{name: name}
}

func (m *Model) Init(conf *recconf.AlgoConfig) error {
	m.conf = conf.PAIModelConf
	if m.conf.Model == "" {
		return errors.New("PAIModelConf.Model is empty")
	}
	if m.conf.APIKey == "" {
		return errors.New("PAIModelConf.APIKey is empty")
	}
	m.apiKey = [REDACTED]
	region := strings.TrimSpace(m.conf.Region)
	if region == "" {
		region = defaultPAIModelRegion
	}
	m.endpoint = fmt.Sprintf(paiModelEndpointFormat, region)
	m.client = newHTTPClient(m.conf.Timeout)
	return nil
}

func (m *Model) Run(algoData interface{}) (interface{}, error) {
	req, ok := algoData.(*ChatCompletionRequest)
	if !ok {
		return nil, errors.New("aichat model expects *ChatCompletionRequest")
	}
	return m.Stream(context.Background(), req, nil)
}

func (m *Model) Stream(ctx context.Context, request *ChatCompletionRequest, onDelta DeltaHandler) (*StreamResult, error) {
	if request == nil {
		return nil, errors.New("aichat request is nil")
	}
	payload := *request
	if payload.Model == "" {
		payload.Model = m.conf.Model
	}
	payload.Stream = true
	body, err := json.Marshal(chatCompletionPayload{
		ChatCompletionRequest: &payload,
		ExtraBody: map[string]string{
			"channel": paiTokenChannel,
		},
	})
	if err != nil {
		return nil, err
	}
	attempts, callID, status := 0, rand.Uint64(), "error"
	defer func() {
		log.Info(fmt.Sprintf("module=AIChatModel\tcallId=%016x\tattempts=%d\tstatus=%s", callID, attempts, status))
	}()
	delivered := false
	// Replaying is safe only before any content reaches the caller.
	var handler DeltaHandler
	if onDelta != nil {
		handler = func(text string) error {
			delivered = true
			return onDelta(text)
		}
	}
	for retry := 0; ; retry++ {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		attempts++
		result, err := m.streamOnce(ctx, body, handler)
		if err == nil {
			status = "ok"
			return result, nil
		}
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		if delivered || retry >= m.conf.RetryTimes {
			return nil, err
		}
		log.Warning(fmt.Sprintf("module=AIChatModel\tcallId=%016x\tevent=retry\tattempt=%d", callID, attempts+1))
	}
}

func (m *Model) streamOnce(ctx context.Context, body []byte, onDelta DeltaHandler) (*StreamResult, error) {
	endpoint := m.endpoint + "/chat/completions"
	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	httpReq.Header.Set("Content-Type", "application/json")
	httpReq.Header.Set("Authorization", "Bearer "+m.apiKey)

	resp, err := m.client.Do(httpReq)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, readErr := io.ReadAll(io.LimitReader(resp.Body, 4096))
		// Drain the rest of the error body so the connection can be reused.
		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
		if readErr != nil {
			return nil, fmt.Errorf("aichat upstream status:%d read body error:%v", resp.StatusCode, readErr)
		}
		if detail := strings.TrimSpace(string(body)); detail != "" {
			return nil, fmt.Errorf("aichat upstream status:%d body:%s", resp.StatusCode, detail)
		}
		return nil, fmt.Errorf("aichat upstream status:%d", resp.StatusCode)
	}
	return parseStream(resp.Body, onDelta)
}

func newHTTPClient(timeout int) *http.Client {
	if timeout <= 0 {
		timeout = defaultPAIModelTimeout
	}
	tr := http.DefaultTransport.(*http.Transport).Clone()
	tr.MaxConnsPerHost = 2000
	tr.MaxIdleConnsPerHost = 2000
	tr.MaxIdleConns = 2000
	tr.ResponseHeaderTimeout = time.Duration(timeout) * time.Millisecond
	return &http.Client{Transport: tr}
}

package searchsuggestion

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"strings"

	"github.com/alibaba/pairec/v2/algorithm/aichat"
)

type toolArguments struct {
	Suggestions []string `json:"suggestions"`
}

func Generate(ctx context.Context, runtimeConfig *RuntimeConfig, input *GenerationInput) Outcome {
	if runtimeConfig == nil || runtimeConfig.Model == nil {
		return Outcome{Err: NewError(CodeModelUnavailable, false, fmt.Errorf("model is unavailable"))}
	}
	payload, inputErr := input.JSON()
	if inputErr != nil {
		return Outcome{Err: inputErr}
	}
	temperature := 0.2
	parallelToolCalls := false
	request := &aichat.ChatCompletionRequest{
		Messages: []aichat.Message{
			{Role: "system", Content: runtimeConfig.Prompt},
			{Role: "user", Content: "UNTRUSTED_SUGGESTION_CONTEXT_JSON:\n" + string(payload)},
		},
		Tools: []aichat.Tool{aichat.SuggestionTool(input.SuggestionCount, runtimeConfig.ToolDescription)},
		ToolChoice: map[string]interface{}{
			"type":     "function",
			"function": map[string]string{"name": "emit_suggestions"},
		},
		Stream:            true,
		EnableThinking:    false,
		Temperature:       &temperature,
		ParallelToolCalls: &parallelToolCalls,
		MaxTokens:         384,
	}
	result, err := runtimeConfig.Model.Stream(ctx, request, nil)
	if err != nil {
		if ctx.Err() != nil {
			return Outcome{Err: NewError(CodeTimeout, true, ctx.Err())}
		}
		return Outcome{Err: NewError(CodeModelError, true, err)}
	}
	suggestions, parseErr := parseResult(result, input.SuggestionCount)
	if parseErr != nil {
		return Outcome{Err: parseErr}
	}
	validated, validationErr := Validate(suggestions, input.SuggestionCount, input.CurrentQuery)
	if validationErr != nil {
		return Outcome{Err: validationErr}
	}
	return Outcome{Suggestions: validated}
}

func parseResult(result *aichat.StreamResult, count int) ([]string, *Error) {
	if result == nil || strings.TrimSpace(result.Content) != "" || len(result.ToolCalls) != 1 {
		return nil, NewError(CodeInvalidStructure, true, fmt.Errorf("exactly one tool call and no prose are required"))
	}
	toolCall := result.ToolCalls[0]
	if strings.TrimSpace(toolCall.ID) == "" || toolCall.Type != "function" || toolCall.Function.Name != "emit_suggestions" {
		return nil, NewError(CodeInvalidStructure, true, fmt.Errorf("invalid emit_suggestions tool call"))
	}
	decoder := json.NewDecoder(bytes.NewBufferString(toolCall.Function.Arguments))
	decoder.DisallowUnknownFields()
	var arguments toolArguments
	if err := decoder.Decode(&arguments); err != nil {
		return nil, NewError(CodeInvalidStructure, true, err)
	}
	if err := decoder.Decode(&struct{}{}); err != io.EOF {
		if err == nil {
			err = fmt.Errorf("multiple JSON values")
		}
		return nil, NewError(CodeInvalidStructure, true, err)
	}
	if len(arguments.Suggestions) != count {
		return nil, NewError(CodeInvalidStructure, true, fmt.Errorf("expected %d suggestions", count))
	}
	return arguments.Suggestions, nil
}

package searchsuggestion

import (
	"fmt"
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"

	"github.com/alibaba/pairec/v2/algorithm/aichat"
	"github.com/alibaba/pairec/v2/log"
	"golang.org/x/text/unicode/norm"
)

var (
	urlPattern      = regexp.MustCompile(`(?i)(https?://|www\.|\b[a-z0-9.-]+\.(com|cn|net|org)\b)`)
	internalPattern = regexp.MustCompile(`(?i)(item[_ -]?id|knowledge[_ -]?id|candidate[_ -]?id|search_goods|emit_suggestions|\[\[citation:|\[[0-9]+\]|【[0-9]+】)`)
	markdownPattern = regexp.MustCompile("(?m)(^\\s{0,3}(#{1,6}|[-*+]\\s|>\\s)|```|`|\\[[^]]*\\]\\([^)]*\\))")
)

func Validate(suggestions []string, count int, currentQuery string) ([]string, *Error) {
	if len(suggestions) != count {
		return nil, NewError(CodeValidationFailed, true, fmt.Errorf("expected %d suggestions, got %d", count, len(suggestions)))
	}
	baseline := normalizeComparable(currentQuery)
	seen := make(map[string]struct{}, len(suggestions))
	validated := make([]string, 0, len(suggestions))
	for _, suggestion := range suggestions {
		suggestion = strings.TrimSpace(norm.NFKC.String(suggestion))
		length := utf8.RuneCountInString(suggestion)
		normalized := normalizeComparable(suggestion)
		_, duplicate := seen[normalized]
		reason := ""
		switch {
		case length < aichat.SuggestionMinLength || length > aichat.SuggestionMaxLength:
			reason = "length"
		case strings.IndexFunc(suggestion, unicode.IsControl) >= 0:
			reason = "control"
		case urlPattern.MatchString(suggestion):
			reason = "url"
		case internalPattern.MatchString(suggestion):
			reason = "internal_marker"
		case markdownPattern.MatchString(suggestion) || strings.ContainsAny(suggestion, "{}<>"):
			reason = "markup"
		case normalized == "" || (baseline != "" && normalized == baseline):
			reason = "repeated_query"
		case duplicate:
			reason = "duplicate"
		}
		if reason != "" {
			log.Warning(fmt.Sprintf("module=SearchSuggestion\tevent=filtered\treason=%s", reason))
			continue
		}
		seen[normalized] = struct{}{}
		validated = append(validated, suggestion)
	}
	if len(validated) == 0 {
		return nil, NewError(CodeValidationFailed, true, fmt.Errorf("no valid suggestions"))
	}
	return validated, nil
}

func normalizeComparable(value string) string {
	value = strings.ToLower(norm.NFKC.String(value))
	var builder strings.Builder
	space := false
	for _, r := range value {
		switch {
		case unicode.IsLetter(r) || unicode.IsDigit(r):
			builder.WriteRune(r)
			space = false
		case unicode.IsSpace(r):
			if builder.Len() > 0 && !space {
				builder.WriteByte(' ')
				space = true
			}
		}
	}
	return strings.TrimSpace(builder.String())
}

